create database hospital_db;

use hospital_db;

create table hospitals(hospital_id varchar(6) not null,
hospital_name varchar(100) not null,
hospital_type varchar(40) not null,
city varchar(50) not null,
state varchar(20) not null,
region varchar(20) not null,
bed_capacity int not null,
established_year int not null,
contact_number varchar(20) not null,
email varchar(100),
constraint hospitals primary key(hospital_id));

create table departments(department_id varchar(6) not null primary key,
department_name varchar(100) not null,
hospital_id varchar(6) not null,
floor_number int not null,
head_doctor_id varchar(10));

use hospital_db;

create table doctors(doctor_id varchar(6) not null Primary key,
first_name varchar(50) not null,
last_name varchar(50) not null,
gender varchar(10) not null,
specialization varchar(50) not null,
department_id varchar(6),
hospital_id varchar(6) not null,
qualification varchar(30) not null,
experience_years int not null,
consultation_fee decimal(10,2) not null,
phone_number varchar(20) not null,
email varchar(50),
joining_date varchar(30) not null);

show tables;

describe hospitals;

show create  table hospitals;

create table patients(patient_id varchar(10) not null primary key,
first_name varchar(20) not null,
last_name varchar(20) not null,
gender varchar(10) not null,
date_of_birth varchar(30) not null,
age int not null,
city varchar(30) not null,
state varchar(30) not null,
phone_number varchar(20) not null,
email varchar(50),
blood_group varchar(5) not null,
registration_date varchar(30) not null);


create table rooms(room_id varchar(10) not null primary key,
hospital_id varchar(6) not null,
room_number int not null,
room_type varchar(20) not null,
floor_number int not null,
daily_charge decimal(10.2) not null,
room_status varchar(20) not null);


create table appointments(appointment_id varchar(10) not null primary key,
patient_id varchar(10) not null,
doctor_id varchar(6) not null,
hospital_id varchar(6) not null,
appointment_date varchar(20) not null,
appointment_time time not null,
status varchar(20) not null,
reason_for_visit varchar(100) not null,
created_at timestamp not null);

drop table admissions;
create table admissions(admission_id varchar(10) not null primary key,
patient_id varchar(10) not null,
hospital_id varchar(6) not null,
department_id varchar(6) not null,
admitting_doctor_id varchar(6) not null,
room_id varchar(10) not null,
admission_date varchar(20) not null,
discharge_date varchar(20),
admission_type varchar(20) not null,
admission_status varchar(20) not null);


create table treatments(treatment_id varchar(10) not null primary key,
admission_id varchar(10),
patient_id varchar(10) not null,
doctor_id varchar(6) not null,
treatment_name varchar(100) not null,
treatment_date date not null,
treatment_cost decimal(10.2) not null,
treatment_status varchar(20) not null);

create table insurance(isurance_id varchar(10) not null primary key,
patient_id varchar(10) not null,
insurance_provider varchar(50) not null,
policy_number varchar(10) not null,
coverage_amount decimal(10.2) not null,
policy_start_date date not null,
policy_end_date date not null,
claim_status varchar(20) not null);

create table medicines(medicine_id varchar(10) not null primary key,
medicine_name varchar(50) not null,
category varchar(30) not null,
manufacture varchar(30) not null,
unit_price decimal(10.2) not null,
stock_quantity int not null);

create table pharmacy(pharmacy_sale_id varchar(10) not null primary key,
patient_id varchar(10) not null,
medicine_id varchar(10) not null,
hospital_id varchar(6) not null,
quantity int not null,
sale_date date not null,
total_price decimal(10.2) not null);

create table laboratory(lab_test_id varchar(10) not null primary key,
patient_id varchar(10) not null,
doctor_id varchar(6) not null,
hospital_id varchar(6) not null,
test_name varchar(50) not null,
test_date date not null,
test_result varchar(10) not null,
test_cost decimal(10.2) not null,
test_status varchar(20) not null);

create table employees(employee_id varchar(10) not null primary key,
first_name varchar(20) not null,
last_name varchar(20) not null,
gender varchar(10) not null,
hospital_id varchar(6) not null,
department_id varchar(6) not null,
designation varchar(20) not null,
employment_type varchar(20) not null,
salary decimal(10.2) not null,
joining_date date not null,
phone_number varchar(15) not null,
email varchar(50) not null);

create table billing(bill_id varchar(10) not null primary key,
patient_id varchar(10) not null,
admission_id varchar(10),
appointment_id varchar(10),
bill_date date not null,
room_charges decimal(10.2) not null,
doctor_charges decimal(10.2) not null,
medicine_charges decimal(10.2) not null,
lab_charges decimal(10.2) not null,
other_charges decimal(10.2) not null,
total_amount decimal(10.2) not null,
bill_status varchar(20) not null);

create table payments(payment_id varchar(10) not null primary key,
bill_id varchar(10) not null,
patient_id varchar(10) not null,
payment_date date not null,
payment_amount decimal(10.2) not null,
payment_mode varchar(20),
payment_status varchar(10) not null);









